#!/usr/bin/env python3
"""Generate .github/robolectric/android-all.txt and levels.txt, the Robolectric jars CI downloads.

android-all.txt maps every API level Robolectric knows to its android-all-instrumented jar version, read from
Robolectric's own build sources (buildSrc AndroidSdk.kt, or AndroidSdk.groovy before 4.14) at the release tag of
the catalog's test-robolectric version. levels.txt lists the levels the unit tests load, scanned from this repo.
CI downloads exactly those jars (robolectric_prefetch.sh, in the unit job of .github/workflows/kotlin-unit-tests.yml)
and the tests run with -Drobolectric.dependency.dir, so a missing level fails the tests.

usage: python3 -I .github/scripts/update_robolectric_jars.py [--check | --check-upstream | --print | --versions]
  (no flag)          regenerate both files (network for the mapping, local scan for the levels)
  --check            offline, for CI: exit 1 if the files are stale for the catalog version or the test sources;
                     a listed level the scan no longer finds is only a warning
  --check-upstream   network: android-all.txt equals Robolectric's sources at its stamped version, and Robolectric's
                     build copy agrees with its runtime copy (DefaultSdkProvider.java)
  --print            print Robolectric's full mapping (default: the catalog version) and exit
  --versions         offline, for robolectric_prefetch.sh: exit 1 unless android-all.txt is for the catalog version
                     and maps every level in levels.txt; else print the jar version of each listed level, one per line
Run it after every Robolectric bump and whenever --check fails. Stdlib only.
"""
import argparse
import glob
import os
import re
import sys
import urllib.error
import urllib.request

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
OUT_DIR = os.path.join(REPO_ROOT, ".github", "robolectric")
ANDROID_ALL = os.path.join(OUT_DIR, "android-all.txt")
LEVELS = os.path.join(OUT_DIR, "levels.txt")
CATALOG = os.path.join(REPO_ROOT, "gradle", "libs.versions.toml")
FIX = "python3 -I .github/scripts/update_robolectric_jars.py"
RAW = "https://raw.githubusercontent.com/robolectric/robolectric/robolectric-{version}/{path}"
BUILD_SOURCES = ["buildSrc/src/main/java/AndroidSdk.kt", "buildSrc/src/main/groovy/AndroidSdk.groovy"]
PROVIDER_SOURCE = "robolectric/src/main/java/org/robolectric/plugins/DefaultSdkProvider.java"

# `AndroidSdk(23, "6.0.1_r3", "r1")` in both AndroidSdk.kt and AndroidSdk.groovy (`new` is optional).
SDK_RE = re.compile(r'\bAndroidSdk\(\s*(\d+)\s*,\s*"([^"]+)"\s*,\s*"([^"]+)"\s*\)')
# `new DefaultSdk(M.SDK_INT, "6.0.1_r3", "r1", ...)` in DefaultSdkProvider.java (levels are symbolic there).
PROVIDER_RE = re.compile(r'\bnew\s+DefaultSdk\(\s*([\w.]+)\s*,\s*"([^"]+)"\s*,\s*"([^"]+)"')
PREINSTRUMENTED_RE = re.compile(r'\bPREINSTRUMENTED_VERSION\s*=\s*(\d+)')
CATALOG_RE = re.compile(r'^test-robolectric\s*=\s*"[^"]*:([^":]+)"', re.MULTILINE)
MIN_SDK_RE = re.compile(r'^minSdk\s*=\s*"(\d+)"', re.MULTILINE)

# Test-source scan. Only literal ints are understood; anything else is an error, never a guess.
CONFIG_RE = re.compile(r'@(?:[\w.]+\.)?Config\(')
SDK_ARG_RE = re.compile(r'\bsdk\s*=\s*')
LITERAL_RE = re.compile(r'(\[\s*\d+(?:\s*,\s*\d+)*\s*\]|\{\s*\d+(?:\s*,\s*\d+)*\s*\}|\d+)\s*(?:,|$)')
ROBOLECTRIC_USE_RE = re.compile(r'\b(?:\w*RobolectricTestRunner|AndroidJUnit4)\b')

LEVELS_HEADER = """\
# GENERATED by .github/scripts/update_robolectric_jars.py; do not edit. Regenerate: {fix}
# The API levels whose Robolectric android-all jars CI downloads (versions in android-all.txt):
#  - every literal @Config(sdk = ...) value in **/src/test*/** (anything non-literal is a scan error;
#    so is any robolectric.properties, which would override the default below);
#  - the highest level Robolectric knows: its compile SDK, which every sandbox loads;
#  - if any test uses Robolectric, the default level of tests without an explicit sdk: the catalog minSdk, set for
#    every module by tests-common's RobolectricDefaultSdk (a GlobalConfigProvider fed via tests-common's
#    BuildConfig from the catalog minSdk).
"""


class Problems(Exception):
    pass


def fail(message):
    sys.exit(f"update_robolectric_jars: {message}")


def rel(path):
    return os.path.relpath(path, REPO_ROOT)


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def catalog_version():
    match = CATALOG_RE.search(read(CATALOG))
    if not match:
        fail(f"no `test-robolectric = \"group:artifact:version\"` line in {rel(CATALOG)}")
    return match.group(1)


def catalog_min_sdk():
    match = MIN_SDK_RE.search(read(CATALOG))
    if not match:
        fail(f"no `minSdk = \"<int>\"` line in [versions] of {rel(CATALOG)}")
    return int(match.group(1))


def fetch(version, path):
    """Returns the file's text, or None if it doesn't exist at that tag."""
    url = RAW.format(version=version, path=path)
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            return response.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        fail(f"{url}: HTTP {e.code}")
    except (urllib.error.URLError, OSError) as e:
        fail(f"{url}: {getattr(e, 'reason', e)}")


def preinstrumented(source, path):
    match = PREINSTRUMENTED_RE.search(source)
    if not match:
        fail(f"no PREINSTRUMENTED_VERSION in {path}")
    return match.group(1)


def upstream_mapping(version):
    """(source path, {level: jar version}) from Robolectric's buildSrc, the list its own build publishes."""
    for path in BUILD_SOURCES:
        source = fetch(version, path)
        if source is None:
            continue
        suffix = preinstrumented(source, path)
        mapping = {int(level): f"{android}-robolectric-{build}-i{suffix}"
                   for level, android, build in SDK_RE.findall(source)}
        if not mapping:
            fail(f"no AndroidSdk(...) entries in {path} at robolectric-{version}")
        return path, mapping
    fail(f"none of {BUILD_SOURCES} exists at tag robolectric-{version} (is {version} a Robolectric release?)")


def provider_versions(version):
    """{jar version: symbolic level} from DefaultSdkProvider.java, the copy the test runtime uses."""
    source = fetch(version, PROVIDER_SOURCE)
    if source is None:
        fail(f"{PROVIDER_SOURCE} doesn't exist at tag robolectric-{version}")
    suffix = preinstrumented(source, PROVIDER_SOURCE)
    return {f"{android}-robolectric-{build}-i{suffix}": symbol
            for symbol, android, build in PROVIDER_RE.findall(source)}


def data_lines(path):
    """(line number, content) for each non-comment, non-blank line."""
    for number, raw in enumerate(read(path).splitlines(), 1):
        content = raw.split("#", 1)[0].strip()
        if content:
            yield number, content


def read_android_all():
    stamp, mapping = None, {}
    for number, content in data_lines(ANDROID_ALL):
        key, sep, value = (part.strip() for part in content.partition("="))
        if key == "robolectric" and sep and value:
            stamp = value
        elif key.isdigit() and sep and value:
            mapping[int(key)] = value
        else:
            fail(f"{rel(ANDROID_ALL)}:{number}: expected `robolectric=X` or `level=version`, got '{content}'. "
                 f"Fix: {FIX}")
    if not stamp or not mapping:
        fail(f"{rel(ANDROID_ALL)} has no robolectric= stamp or no levels. Fix: {FIX}")
    return stamp, mapping


def read_levels():
    levels = set()
    for number, content in data_lines(LEVELS):
        if not content.isdigit():
            fail(f"{rel(LEVELS)}:{number}: not an API level: '{content}'. Fix: {FIX}")
        levels.add(int(content))
    return levels


def parse_config(path, number, line, rest):
    """Literal sdk levels of one `@Config(` occurrence; raises Problems for anything else."""
    depth, end = 1, None
    for i, char in enumerate(rest):
        depth += {"(": 1, ")": -1}.get(char, 0)
        if depth == 0:
            end = i
            break
    where = f"{rel(path)}:{number}"
    if end is None:
        raise Problems(f"{where}: multi-line @Config(...); keep it on one line so the sdk levels can be scanned")
    args = rest[:end]
    if re.search(r'\b(?:minSdk|maxSdk)\b', args):
        raise Problems(f"{where}: @Config minSdk/maxSdk isn't supported by the scan; list the levels with sdk = [...]")
    sdk = SDK_ARG_RE.search(args)
    if not sdk:
        return set()
    literal = LITERAL_RE.match(args[sdk.end():].strip())
    if not literal:
        raise Problems(f"{where}: @Config sdk must be a literal int or int list, got '{line.strip()}'")
    return {int(n) for n in re.findall(r'\d+', literal.group(1))}


def robolectric_properties():
    """Every robolectric.properties in the repo, skipping build/ and hidden directories (.git, .gradle, ...)."""
    found = []
    for directory, subdirs, files in os.walk(REPO_ROOT):
        subdirs[:] = [d for d in subdirs if d != "build" and not d.startswith(".")]
        if "robolectric.properties" in files:
            found.append(os.path.join(directory, "robolectric.properties"))
    return sorted(found)


def in_build_dir(path):
    """True when a component of the path relative to the repo root is a build directory."""
    relative = os.path.relpath(path, REPO_ROOT)
    return "build" in relative.split(os.sep)


def scan_levels(mapping, min_sdk):
    """(levels, problems): the levels the unit tests load, and every construct the scan refuses to guess."""
    problems = []
    for props in robolectric_properties():
        problems.append(f"{rel(props)}: robolectric.properties would override tests-common's RobolectricDefaultSdk "
                        f"(the catalog minSdk default) and isn't supported by the scan; delete it and use "
                        f"@Config(sdk = [...])")
    levels = {max(mapping)}
    sources = []
    for ext in ("kt", "java"):
        # Every unit-test source set: src/test, src/testDebug, src/testRelease, ...
        sources += glob.glob(os.path.join(REPO_ROOT, "**", "src", "test*", "**", f"*.{ext}"), recursive=True)
    for path in sorted(p for p in sources if not in_build_dir(p)):
        text = read(path)
        if ROBOLECTRIC_USE_RE.search(text):
            # Default level of tests without an explicit sdk: tests-common's RobolectricDefaultSdk, which
            # gets the catalog minSdk via tests-common's BuildConfig for every module.
            levels.add(min_sdk)
        for number, line in enumerate(text.splitlines(), 1):
            for match in CONFIG_RE.finditer(line):
                try:
                    levels |= parse_config(path, number, line, line[match.end():])
                except Problems as e:
                    problems.append(str(e))
    return levels, problems


def write_files(version, source, mapping, levels):
    os.makedirs(OUT_DIR, exist_ok=True)
    with open(ANDROID_ALL, "w", encoding="utf-8") as f:
        f.write(f"# GENERATED by .github/scripts/update_robolectric_jars.py; do not edit. Regenerate: {FIX}\n"
                f"# android-all-instrumented jar version per API level, from robolectric/robolectric {source}\n"
                f"# at tag robolectric-{version}. The robolectric= stamp must match test-robolectric in "
                f"gradle/libs.versions.toml.\n"
                f"robolectric={version}\n")
        f.writelines(f"{level}={mapping[level]}\n" for level in sorted(mapping))
    with open(LEVELS, "w", encoding="utf-8") as f:
        f.write(LEVELS_HEADER.format(fix=FIX))
        f.writelines(f"{level}\n" for level in sorted(levels))


def list_errors(stamp, mapping, listed):
    """What --check and --versions both reject: lists for another Robolectric version, or levels they can't map."""
    errors = []
    version = catalog_version()
    if stamp != version:
        errors.append(f"{rel(ANDROID_ALL)} is for Robolectric {stamp}, but {rel(CATALOG)} has {version}")
    if not listed:
        errors.append(f"{rel(LEVELS)} lists no levels")
    if listed - set(mapping):
        errors.append(f"{rel(LEVELS)} lists level(s) {sorted(listed - set(mapping))} that Robolectric {stamp} "
                      f"doesn't know (known: {sorted(mapping)})")
    return errors


def check():
    """Offline. Returns the exit status."""
    stamp, mapping = read_android_all()
    listed = read_levels()
    errors, warnings = list_errors(stamp, mapping, listed), []
    scanned, problems = scan_levels(mapping, catalog_min_sdk())
    for problem in problems:
        print(f"::error::{problem}. Fix: change the source as described, then run {FIX}")
    if not problems:
        if scanned - listed:
            errors.append(f"{rel(LEVELS)} is missing level(s) {sorted(scanned - listed)} that the tests load")
        if listed - scanned:
            warnings.append(f"{rel(LEVELS)} lists level(s) {sorted(listed - scanned)} that the scan no longer "
                            f"finds (downloaded but unused)")
    for warning in warnings:
        print(f"::warning::{warning}. Fix: {FIX}")
    for error in errors:
        print(f"::error::{error}. Fix: {FIX}")
    if errors or problems:
        return 1
    print(f"Robolectric jar lists up to date: Robolectric {stamp}, levels {sorted(listed)}")
    return 0


def versions():
    """Offline. Prints the jar version of every listed level; returns the exit status."""
    stamp, mapping = read_android_all()
    listed = read_levels()
    errors = list_errors(stamp, mapping, listed)
    for error in errors:
        print(f"::error::{error}. Fix: {FIX}", file=sys.stderr)
    if errors:
        return 1
    print("\n".join(mapping[level] for level in sorted(listed)))
    return 0


def check_upstream():
    stamp, mapping = read_android_all()
    source, upstream = upstream_mapping(stamp)
    status = 0
    if mapping != upstream:
        status = 1
        print(f"{rel(ANDROID_ALL)} differs from {source} at robolectric-{stamp}:")
        for level in sorted(set(mapping) | set(upstream)):
            if mapping.get(level) != upstream.get(level):
                print(f"  {level}: listed {mapping.get(level, '(none)')}, upstream {upstream.get(level, '(none)')}")
        print(f"Fix: {FIX}")
    else:
        print(f"{rel(ANDROID_ALL)} matches {source} at robolectric-{stamp} ({len(upstream)} levels)")
    runtime = provider_versions(stamp)
    only_build = sorted(set(upstream.values()) - set(runtime))
    only_runtime = sorted(set(runtime) - set(upstream.values()))
    if only_build or only_runtime:
        status = 1
        print(f"Robolectric {stamp}'s two copies of the mapping disagree ({source} vs {PROVIDER_SOURCE}):")
        for jar in only_build:
            print(f"  only in {os.path.basename(source)}: {jar}")
        for jar in only_runtime:
            print(f"  only in DefaultSdkProvider.java: {jar} ({runtime[jar]})")
    else:
        print(f"Cross-check: {os.path.basename(source)} and DefaultSdkProvider.java agree ({len(runtime)} SDKs)")
    return status


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n", 1)[0])
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="offline staleness check (CI)")
    mode.add_argument("--check-upstream", action="store_true",
                      help="compare android-all.txt with Robolectric's sources")
    mode.add_argument("--print", action="store_true", help="print Robolectric's full mapping and exit")
    mode.add_argument("--versions", action="store_true", help="validate the lists, print the jar versions (prefetch)")
    parser.add_argument("--robolectric-version", help="for --print and the default run; default: the catalog's")
    args = parser.parse_args()

    if args.check:
        return check()
    if args.check_upstream:
        return check_upstream()
    if args.versions:
        return versions()
    version = args.robolectric_version or catalog_version()
    source, mapping = upstream_mapping(version)
    if args.print:
        print(f"# Robolectric {version}, from {source}")
        for level in sorted(mapping):
            print(f"{level}={mapping[level]}")
        return 0
    levels, problems = scan_levels(mapping, catalog_min_sdk())
    if problems:
        for problem in problems:
            print(f"::error::{problem}", file=sys.stderr)
        fail("the test-source scan failed; nothing written")
    write_files(version, source, mapping, levels)
    print(f"{rel(ANDROID_ALL)}: Robolectric {version}, {len(mapping)} levels (from {source})")
    print(f"{rel(LEVELS)}: {sorted(levels)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
